// Brand pieces shared by every screen: the wordmark (the only way the name is ever set), the
// house four-point star, the deco rule and fan, panel headers, and faction heraldry by size.
import type { CSSProperties, ReactNode } from 'react';
import logoUrl from '../assets/icons/logo-legatum.svg?url';
import { inkOfColor } from '../theme';

const crests = import.meta.glob<string>('../assets/heraldry/raster/crest-*-512.png', { eager: true, query: '?url', import: 'default' });
// Seals, glyphs and crests are the 2026-11-21 historical set, all eleven generated by heraldry/src (this line also refreshes the shared glob transform cache).
const seals = import.meta.glob<string>('../assets/heraldry/seal-*.svg', { eager: true, query: '?url', import: 'default' });
const glyphs = import.meta.glob<string>('../assets/heraldry/glyph-*.svg', { eager: true, query: '?url', import: 'default' });
// 2026-11-15: Egypt and Rome portraits refresh Vitest's per-file glob transform cache.
const portraits = import.meta.glob<string>('../assets/art/people-*-360.jpg', { eager: true, query: '?url', import: 'default' });
const pick = (m: Record<string, string>, faction: string) => {
  const id = faction.toLowerCase();
  return Object.entries(m).find(([k]) => k.includes(`-${id}.`) || k.includes(`-${id}-`))?.[1] ?? null;
};
const factionLabel = (faction: string): string => ({
  Switzerland: 'Switzerland', India: 'India', Byzantium: 'Byzantium', Germany: 'Germany',
  Celts: 'Celts', Mongols: 'Mongols', Sparta: 'Sparta', Athens: 'Athens', Aztecs: 'Aztecs', Egypt: 'Egypt', Rome: 'Rome',
} as Record<string, string>)[faction] ?? faction;

const STAR_PATH = 'M0 -5L.95 -.95L5 0L.95 .95L0 5L-.95 .95L-5 0L-.95 -.95Z';

/** The wordmark, tinted by --wordmark (or `color`). Aspect 236:50. */
export function Wordmark({ height = 24, color, className }: { height?: number; color?: string; className?: string }) {
  const style: CSSProperties = {
    width: (height * 236) / 50,
    height,
    backgroundColor: color ?? 'var(--wordmark)',
    WebkitMaskImage: `url("${logoUrl}")`,
    maskImage: `url("${logoUrl}")`,
  };
  return <span role="img" aria-label="Legatum" className={`wordmark ${className ?? ''}`} style={style} />;
}

export function Star({ size = 10, className }: { size?: number; className?: string }) {
  return (
    <svg className={`star ${className ?? ''}`} width={size} height={size} viewBox="-5 -5 10 10" aria-hidden>
      <path d={STAR_PATH} fill="currentColor" />
    </svg>
  );
}

/** A rule ending in a diamond used around the title kicker; `flip` mirrors it. */
export function DecoRule({ width = 48, flip }: { width?: number; flip?: boolean }) {
  return (
    <svg className="deco-rule" width={width} height="8" viewBox={`0 0 ${width} 8`} aria-hidden style={flip ? { transform: 'scaleX(-1)' } : undefined}>
      <path d={`M0 4H${width - 10}`} stroke="currentColor" strokeWidth="1" />
      <path d={`M${width - 8} 4l4 -4l4 4l-4 4z`} fill="currentColor" />
    </svg>
  );
}

/** Deco sunburst: the house star over nine rays (at most one per screen region). */
export function Fan({ width = 48 }: { width?: number }) {
  return (
    <svg className="fan" width={width} height={width / 2} viewBox="-28 -28 56 28" aria-hidden>
      {Array.from({ length: 9 }, (_, i) => {
        const a = (Math.PI * (i + 1)) / 10;
        const r = i % 2 ? 22 : 27;
        return <line key={i} x1={-Math.cos(a) * 9} y1={-Math.sin(a) * 9} x2={-Math.cos(a) * r} y2={-Math.sin(a) * r} stroke="currentColor" strokeWidth=".8" />;
      })}
      <path d="M-7 0a7 7 0 0 1 14 0" fill="none" stroke="currentColor" strokeWidth=".8" />
      <path d={STAR_PATH} transform="translate(0 -1) scale(.8)" fill="currentColor" />
    </svg>
  );
}

/**
 * Panel header with a centered display title and an italic subtitle.
 */
export function PanelHead({ title, sub, right, kicker }: { title: ReactNode; sub?: ReactNode; right?: ReactNode; kicker?: ReactNode }) {
  return (
    <header className="ph">
      {kicker && <div className="ph-kicker">{kicker}</div>}
      <div className="ph-title">
        <h3>{title}</h3>
      </div>
      {sub && <p className="ph-sub">{sub}</p>}
      {right && <div className="ph-right">{right}</div>}
    </header>
  );
}

/** The paired historical people portrait (360 px JPEG) for a faction. */
export function leaderPortraitUrl(faction: string): string | null {
  return pick(portraits, faction);
}

function crestUrl(faction: string): string | null {
  return pick(crests, faction);
}

/** Faction mark by size: glyph below 40 px, the tintable seal at 40 px and up. */
export function FactionSeal({ faction, size = 24, color }: { faction: string; size?: number; color?: string }) {
  const url = size >= 40 ? pick(seals, faction) ?? pick(glyphs, faction) : pick(glyphs, faction);
  if (!url) return null;
  return (
    <span
      role="img"
      aria-label={factionLabel(faction)}
      className="faction-mark"
      style={{ width: size, height: size, backgroundColor: color ?? 'currentColor', WebkitMaskImage: `url("${url}")`, maskImage: `url("${url}")` }}
    />
  );
}

/** The grand raster crest (gold on navy) in a framed roundel, for setup and victory screens. */
export function Crest({ faction, size = 96, color }: { faction: string; size?: number; color?: string }) {
  const url = crestUrl(faction);
  return (
    <span className="crest" style={{ width: size, height: size, ['--pc' as string]: color ? inkOfColor(color) : 'var(--accent)' }}>
      {url ? <img src={url} alt={factionLabel(faction)} draggable={false} /> : <FactionSeal faction={faction} size={size * 0.6} color="#e4c36b" />}
    </span>
  );
}

/** Medallion or chit (by look) holding a small faction glyph ring-colored by player. */
export function CrestMedallion({ faction, size = 26, color }: { faction: string; size?: number; color: string }) {
  // Seat colours are bright (made for the map); on parchment the ring and glyph use the seat's ink shade (steel is 1.1:1 otherwise).
  const ink = inkOfColor(color);
  return (
    <span className="medallion" style={{ width: size, height: size, ['--pc' as string]: ink }}>
      <FactionSeal faction={faction} size={Math.round(size * 0.62)} color={ink} />
    </span>
  );
}

const ROMAN = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI', 'XII'];
export const roman = (n: number) => ROMAN[n - 1] ?? String(n);
